package ardupilotmega_test

import (
	"testing"

	"github.com/stretchr/testify/require"

	dialectpkg "github.com/bluenviron/gomavlib/v4/pkg/dialects/ardupilotmega"
)

func TestEnum_GIMBAL_AXIS_CALIBRATION_STATUS(t *testing.T) {
	t.Run("zero", func(t *testing.T) {
		var e dialectpkg.GIMBAL_AXIS_CALIBRATION_STATUS
		e.UnmarshalText([]byte{})
		e.MarshalText()
		e.String()
	})

	t.Run("first entry", func(t *testing.T) {
		enc, err := dialectpkg.GIMBAL_AXIS_CALIBRATION_STATUS_IN_PROGRESS.MarshalText()
		require.NoError(t, err)

		var dec dialectpkg.GIMBAL_AXIS_CALIBRATION_STATUS
		err = dec.UnmarshalText(enc)
		require.NoError(t, err)

		require.Equal(t, dialectpkg.GIMBAL_AXIS_CALIBRATION_STATUS_IN_PROGRESS, dec)
	})
}
